package com.nexusdrive.metadata.service.impl;import com.nexusdrive.metadata.entity.FileMetadata;import com.nexusdrive.metadata.repository.*;import com.nexusdrive.metadata.service.ChunkOrchestrationService;import org.slf4j.*;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class PhysicalCleanupService{private static final Logger log=LoggerFactory.getLogger(PhysicalCleanupService.class);private final FileMetadataRepository files;private final ChunkRepository chunks;private final ChunkOrchestrationService storage;public PhysicalCleanupService(FileMetadataRepository f,ChunkRepository c,ChunkOrchestrationService s){files=f;chunks=c;storage=s;}@Scheduled(fixedDelayString="${cleanup.interval-ms:30000}")public void scan(){files.findTop100ByStatusOrderByUpdatedAtAsc(FileMetadata.Status.DELETED).forEach(this::cleanup);}@Transactional public void cleanup(FileMetadata f){var owned=chunks.findByFileIdOrderByChunkIndex(f.getId());try{for(var c:owned)if(chunks.countByStorageKeyAndFileStatus(c.getStorageKey(),FileMetadata.Status.ACTIVE)==0)storage.delete(c.getStorageNodeId(),c.getStorageKey());chunks.deleteAll(owned);}catch(RuntimeException e){log.warn("Cleanup for file {} will be retried",f.getId(),e);}}}
